def _drive(path: Path, seq: list[tuple]) -> tuple[int | None, int, int]:
    """Drive a sequence element by element.

    Returns (conflict_index, prefix_line_count, total_ops).
    - conflict_index: index of the first conflicting element, or None.
    - prefix_line_count: line count at the moment of conflict (pre-state).
    - total_ops: total length of the sequence.
